import{_ as t,o as a,c as o,a2 as i}from"./chunks/framework.BWuWLRhz.js";const g=JSON.parse('{"title":"Search Syntax","description":"","frontmatter":{},"headers":[],"relativePath":"user-guide/search-syntax.md","filePath":"user-guide/search-syntax.md","lastUpdated":1788596486000}'),s={name:"user-guide/search-syntax.md"};function n(d,e,r,l,c,p){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="search-syntax" tabindex="-1">Search Syntax <a class="header-anchor" href="#search-syntax" aria-label="Permalink to &quot;Search Syntax&quot;">​</a></h1><p>Lertaro&#39;s search bar supports far more than simple plain-text search. Equipped with a blazing-fast matching algorithm, it supports fuzzy jump matching, boolean logic, word boundary operators, drive and path scoping, secondary filtering query tokens, and multilingual aliases. All syntaxes can be freely mixed within the same query.</p><h2 id="_1-basic-matching-case-sensitivity" tabindex="-1">1. Basic Matching &amp; Case Sensitivity <a class="header-anchor" href="#_1-basic-matching-case-sensitivity" aria-label="Permalink to &quot;1. Basic Matching &amp; Case Sensitivity&quot;">​</a></h2><h3 id="fuzzy-matching-default" tabindex="-1">Fuzzy matching (default) <a class="header-anchor" href="#fuzzy-matching-default" aria-label="Permalink to &quot;Fuzzy matching (default)&quot;">​</a></h3><p>Lertaro enables Fuzzy Matching by default. Simply enter any characters in order, and it will match even if the characters are scattered across the file or folder name:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Input Example</th><th style="text-align:left;">Matching Result</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;"><code>ltro</code></td><td style="text-align:left;"><code>Lertaro.exe</code></td><td style="text-align:left;">Characters match sequentially: <code>l</code> → <code>t</code> → <code>r</code> → <code>o</code> (<strong>L</strong>er<strong>t</strong>a<strong>ro</strong>.exe)</td></tr><tr><td style="text-align:left;"><code>vsc</code></td><td style="text-align:left;"><code>Visual Studio Code.lnk</code></td><td style="text-align:left;">Matches initial letters of each word (<strong>V</strong>isual <strong>S</strong>tudio <strong>C</strong>ode)</td></tr><tr><td style="text-align:left;"><code>rt-fin</code></td><td style="text-align:left;"><code>Q3-report-final.docx</code></td><td style="text-align:left;">Matches contiguous substring (Q3-repo<strong>rt-fin</strong>al.docx)</td></tr></tbody></table><p>Turn this off under <strong>Settings → General → System → Enable fuzzy matching</strong> and plain search terms (without operators) will require a contiguous substring — <code>abc</code> will only match names containing contiguous <code>abc</code>, no longer matching <code>a-b-c</code>. This toggle only affects bare terms; all operators described below maintain their exact behaviors either way.</p><h3 id="smart-case-sensitivity" tabindex="-1">Smart Case Sensitivity <a class="header-anchor" href="#smart-case-sensitivity" aria-label="Permalink to &quot;Smart Case Sensitivity&quot;">​</a></h3><ul><li><strong>All-lowercase queries</strong>: Case-insensitive by default. For example, <code>myfile</code> matches <code>myfile</code>, <code>MyFile</code>, <code>MYFILE</code>, etc.</li><li><strong>Queries with uppercase letters</strong>: Once a term contains any uppercase letter, it automatically becomes <strong>case-sensitive</strong>. For example, <code>MyFile</code> matches <code>MyFile</code>, but not lowercase <code>myfile</code>.</li></ul><h2 id="_2-multiple-terms-boolean-logic" tabindex="-1">2. Multiple Terms &amp; Boolean Logic <a class="header-anchor" href="#_2-multiple-terms-boolean-logic" aria-label="Permalink to &quot;2. Multiple Terms &amp; Boolean Logic&quot;">​</a></h2><h3 id="space-and" tabindex="-1">Space: AND <a class="header-anchor" href="#space-and" aria-label="Permalink to &quot;Space: AND&quot;">​</a></h3><p>Separate multiple search terms with spaces to require all conditions to be met. The order in which terms appear in the filename <strong>does not matter</strong>:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>report final 2024</span></span></code></pre></div><p>The above query matches both <code>2024-Q3-report-final.docx</code> and <code>final_report_2024.pdf</code>.</p><h3 id="pipe-or" tabindex="-1">Pipe <code>|</code>: OR <a class="header-anchor" href="#pipe-or" aria-label="Permalink to &quot;Pipe `|`: OR&quot;">​</a></h3><p>Use a pipe symbol <code>|</code> to separate terms where matching any single alternative is sufficient:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>png | jpg | gif</span></span></code></pre></div><p>You can freely combine AND and OR logic:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>report | summary 2024</span></span></code></pre></div><p>This finds files matching either <code>report</code> or <code>summary</code>, and also containing <code>2024</code>. In OR queries, all matched terms across hit branches are highlighted simultaneously in the result name.</p><h3 id="operator-precedence-or-binds-tighter-than-and" tabindex="-1">Operator Precedence: OR binds tighter than AND <a class="header-anchor" href="#operator-precedence-or-binds-tighter-than-and" aria-label="Permalink to &quot;Operator Precedence: OR binds tighter than AND&quot;">​</a></h3><p>When spaces (AND) and the pipe <code>|</code> (OR) are mixed in a single query, <code>|</code> has <strong>higher</strong> precedence than spaces: the terms on both sides of <code>|</code> are merged into one OR group first, and the space-separated groups are then ANDed together. Parentheses are not supported, so this binding order cannot be changed.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>report | summary 2024 | draft</span></span></code></pre></div><p>is equivalent to <code>(report OR summary) AND (2024 OR draft)</code>.</p><p>Note: <code>|</code> must be a standalone token with spaces on both sides — <code>a|b</code> or <code>a |b</code> is not parsed as OR. Do not put an <code>!</code> exclusion term inside a <code>|</code> OR group either (e.g. <code>b | !c</code>), which is parsed as &quot;b matches or c does not&quot;; to exclude a term globally, give it its own space-separated AND condition instead (e.g. <code>b !c</code>).</p><h3 id="escaping-spaces-quoted-phrases" tabindex="-1">Escaping Spaces &amp; Quoted Phrases <a class="header-anchor" href="#escaping-spaces-quoted-phrases" aria-label="Permalink to &quot;Escaping Spaces &amp; Quoted Phrases&quot;">​</a></h3><p>To search for a phrase containing spaces within a single term, escape the space with a backslash <code>\\ </code>, or enclose the phrase in single quotes <code>&#39;...&#39;</code> or double quotes <code>&quot;...&quot;</code>:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>final\\ report</span></span>\n<span class="line"><span>&#39;final report&#39;</span></span></code></pre></div><p>Both examples treat <code>final report</code> as a single phrase with space, rather than splitting it into two independent AND terms.</p><h3 id="pasting-multiple-lines-folded-into-or" tabindex="-1">Pasting Multiple Lines Folded into OR <a class="header-anchor" href="#pasting-multiple-lines-folded-into-or" aria-label="Permalink to &quot;Pasting Multiple Lines Folded into OR&quot;">​</a></h3><p>When copying multi-line text (such as filenames from a spreadsheet, text file, or log) and pasting it directly into the search bar, Lertaro automatically folds the lines into a single OR query separated by <code>|</code> (blank lines are automatically skipped):</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>123</span></span>\n<span class="line"><span>456</span></span>\n<span class="line"><span>678</span></span></code></pre></div><p>Pastes automatically as:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>123 | 456 | 678</span></span></code></pre></div><h2 id="_3-search-operators-cheat-sheet" tabindex="-1">3. Search Operators Cheat Sheet <a class="header-anchor" href="#_3-search-operators-cheat-sheet" aria-label="Permalink to &quot;3. Search Operators Cheat Sheet&quot;">​</a></h2><h3 id="operators-table" tabindex="-1">Operators Table <a class="header-anchor" href="#operators-table" aria-label="Permalink to &quot;Operators Table&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Operator / Syntax</th><th style="text-align:left;">Type</th><th style="text-align:left;">Description</th><th style="text-align:left;">Input Example</th><th style="text-align:left;">Matching Result Example</th></tr></thead><tbody><tr><td style="text-align:left;"><em>(none)</em></td><td style="text-align:left;">Default Fuzzy</td><td style="text-align:left;">Characters appear in order anywhere in name (when fuzzy is on)</td><td style="text-align:left;"><code>report</code></td><td style="text-align:left;"><code>Q3-report-final.docx</code></td></tr><tr><td style="text-align:left;"><code>!</code></td><td style="text-align:left;">Exclude</td><td style="text-align:left;">Excludes all results whose name contains this exact substring</td><td style="text-align:left;"><code>!temp</code></td><td style="text-align:left;">Filters out files containing <code>temp</code></td></tr><tr><td style="text-align:left;"><code>&#39;</code></td><td style="text-align:left;">Flip Exactness</td><td style="text-align:left;">Exact substring when fuzzy is on; fuzzy when fuzzy is off</td><td style="text-align:left;"><code>&#39;report</code></td><td style="text-align:left;">Must contain contiguous substring <code>report</code></td></tr><tr><td style="text-align:left;"><code>&#39;...&#39;</code></td><td style="text-align:left;">Word Boundary</td><td style="text-align:left;">Exact substring matched on word boundaries (not inside larger word)</td><td style="text-align:left;"><code>&#39;app&#39;</code></td><td style="text-align:left;">Matches <code>app.exe</code>, <code>my-app.log</code>; does not match <code>whatsapp.exe</code></td></tr><tr><td style="text-align:left;"><code>^</code></td><td style="text-align:left;">Prefix Match</td><td style="text-align:left;">Name must start with this text</td><td style="text-align:left;"><code>^IMG</code></td><td style="text-align:left;"><code>IMG_20240101.jpg</code> (does not match <code>MY_IMG.jpg</code>)</td></tr><tr><td style="text-align:left;"><code>$</code></td><td style="text-align:left;">Suffix Match</td><td style="text-align:left;">Name must end with this text</td><td style="text-align:left;"><code>.pdf$</code></td><td style="text-align:left;"><code>document.pdf</code> (does not match <code>document.pdf.bak</code>)</td></tr><tr><td style="text-align:left;"><code>^...$</code></td><td style="text-align:left;">Exact Match</td><td style="text-align:left;">Name must equal this text exactly</td><td style="text-align:left;"><code>^readme.md$</code></td><td style="text-align:left;">Matches only <code>readme.md</code></td></tr><tr><td style="text-align:left;"><code>|</code></td><td style="text-align:left;">OR Logic</td><td style="text-align:left;">Matches either side of the pipe</td><td style="text-align:left;"><code>doc | pdf</code></td><td style="text-align:left;">Matches names containing <code>doc</code> or <code>pdf</code></td></tr></tbody></table><h3 id="detailed-operator-behaviors-combinations" tabindex="-1">Detailed Operator Behaviors &amp; Combinations <a class="header-anchor" href="#detailed-operator-behaviors-combinations" aria-label="Permalink to &quot;Detailed Operator Behaviors &amp; Combinations&quot;">​</a></h3><ol><li><strong>Exclusion <code>!</code></strong>: <code>!term</code> directly excludes results containing <code>term</code> as an exact substring. Excluded terms do not undergo pinyin/alias expansion to avoid over-exclusion.</li><li><strong>Exactness Flip <code>&#39;</code></strong>: When global fuzzy matching is enabled, prefixing <code>&#39;</code> forces a specific term to match as an exact substring. <ul><li>For example, <code>lertaro &#39;v1.2</code> performs a fuzzy search for <code>lertaro</code> while requiring <code>v1.2</code> as an exact contiguous substring.</li><li>Exact terms still match filenames that carry pinyin aliases: <code>&#39;exe$</code> also finds <code>古恩希尔</code>, whose pinyin maps to <code>gexe</code>.</li></ul></li><li><strong>Word Boundary Exact Match <code>&#39;...&#39;</code></strong>: Enclosing a single word in quotes (e.g. <code>&#39;app&#39;</code>) checks for word boundaries (spaces, punctuation, hyphens, underscores, or string boundaries), preventing false positives inside larger words.</li><li><strong>Exact Match <code>^...$</code></strong>: Only applies when <code>^</code> and <code>$</code> wrap the <strong>same word</strong>. When used on separate words (e.g. <code>^src md$</code>), they remain separate prefix and suffix filters.</li></ol><p><strong>Operator Combination Examples</strong>:</p><ul><li><code>^IMG !.png$ 2024</code>: Finds files starting with <code>IMG</code>, containing <code>2024</code>, and <strong>not</strong> ending in <code>.png</code>.</li><li><code>&#39;data | &#39;backup ^2024 .zip$</code>: Finds archives starting with <code>2024</code>, ending in <code>.zip</code>, and containing the exact substring <code>data</code> or <code>backup</code>.</li><li><code>^report &#39;公告 | &#39;gw .pdf$ !draft</code>: Finds names starting with <code>report</code>, ending in <code>.pdf</code>, without <code>draft</code>, and exactly containing <code>公告</code>, <code>gw</code>, <code>公文</code>, or other text combinations matching the <code>gw</code> pinyin (<code>&#39;公告 | &#39;gw</code> forms one OR group; the remaining space-separated conditions are ANDed with it).</li></ul><h2 id="_4-path-mode-drive-scoping" tabindex="-1">4. Path Mode &amp; Drive Scoping <a class="header-anchor" href="#_4-path-mode-drive-scoping" aria-label="Permalink to &quot;4. Path Mode &amp; Drive Scoping&quot;">​</a></h2><h3 id="targeting-a-drive" tabindex="-1">Targeting a Drive <a class="header-anchor" href="#targeting-a-drive" aria-label="Permalink to &quot;Targeting a Drive&quot;">​</a></h3><p>Start your query with a drive letter followed by a colon to restrict results strictly to that drive:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>d: report</span></span></code></pre></div><p>The space is optional: <code>d:report</code> and <code>d: report</code> are identical.</p><h3 id="full-path-mode" tabindex="-1">Full Path Mode <a class="header-anchor" href="#full-path-mode" aria-label="Permalink to &quot;Full Path Mode&quot;">​</a></h3><p>When your search query contains path separators (<code>\\</code> or <code>/</code>), Lertaro automatically switches to full path matching mode:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>D:\\Projects\\Lertaro</span></span></code></pre></div><p>Ending with a path separator (e.g. <code>D:\\Projects\\</code>) searches the direct contents <strong>inside</strong> that folder.</p><h3 id="folder-matching-fallback" tabindex="-1">Folder Matching Fallback <a class="header-anchor" href="#folder-matching-fallback" aria-label="Permalink to &quot;Folder Matching Fallback&quot;">​</a></h3><p>When searching by filename alone does not fill the result capacity, Lertaro automatically uses query terms not matched in the filename to match ancestor folder names without requiring special syntax:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>d01j dcj</span></span></code></pre></div><p>Even if <code>dcj</code> never appears in the file&#39;s own name, Lertaro finds <code>d01j.txt</code> located in a folder named (or aliased to) <code>dcj</code>.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>This requires at least one term to match the filename itself, and only triggers when name-only matches have not filled the results. Fallback results are always ranked after direct filename matches.</p></div><h2 id="_5-query-tokens-secondary-filtering" tabindex="-1">5. Query Tokens &amp; Secondary Filtering <a class="header-anchor" href="#_5-query-tokens-secondary-filtering" aria-label="Permalink to &quot;5. Query Tokens &amp; Secondary Filtering&quot;">​</a></h2><p>Lertaro supports appending <strong>Query Tokens</strong> guided by a colon prefix <code>:</code> (customizable in <strong>Settings → General → System → Query Token Global Prefix Character</strong>) to perform chained secondary filtering and sorting on primary results.</p><p>Multiple tokens can be combined in a single <code>:</code> suffix separated by commas <code>,</code>, such as <code>report :@doc,M-,:-F</code>.</p><h3 id="category-filters-category" tabindex="-1">Category Filters (<code>:@&lt;category&gt;</code>) <a class="header-anchor" href="#category-filters-category" aria-label="Permalink to &quot;Category Filters (`:@&lt;category&gt;`)&quot;">​</a></h3><p>Quickly apply preset file extension category rules, supporting <code>|</code> combinations:</p><ul><li><code>:@doc</code>: Documents (<code>*.doc; *.docx; *.pdf; *.txt; *.ppt; *.pptx; *.xls; *.xlsx; *.csv; *.rtf; *.md; *.wps</code>)</li><li><code>:@img</code>: Images (<code>*.jpg; *.jpeg; *.png; *.gif; *.bmp; *.webp; *.ico; *.svg; *.tif; *.tiff; *.psd; *.ai</code>)</li><li><code>:@video</code>: Videos (<code>*.mp4; *.mkv; *.avi; *.mov; *.wmv; *.flv; *.m4v; *.webm; *.3gp; *.rmvb; *.ts</code>)</li><li><code>:@audio</code>: Audio (<code>*.mp3; *.wav; *.flac; *.aac; *.ogg; *.m4a; *.wma; *.ape</code>)</li><li><code>:@zip</code>: Archives (<code>*.zip; *.rar; *.7z; *.tar; *.gz; *.bz2; *.xz; *.iso</code>)</li></ul><p><strong>Examples</strong>:</p><ul><li><code>financial :@doc</code>: Search for &quot;financial&quot; among documents.</li><li><code>wallpaper :@img</code>: Search for &quot;wallpaper&quot; among images.</li><li><code>clip :@video|audio</code>: Search for &quot;clip&quot; among videos or audio files.</li></ul><p>You can customize rules or add new categories under <strong>Settings → Plugins → CoreExtensions</strong>.</p><p>The full search window&#39;s left type-filter sidebar is configured separately in the same plugin&#39;s <strong>Search Filters</strong> group. Sidebar filter names are display-only; <code>@keyword</code> references are parsed only inside a sidebar filter rule and refer to keywords from the <strong>Custom Filters</strong> list, including disabled custom filters.</p><h3 id="specific-extension-filters-ext-or-ext1-ext2" tabindex="-1">Specific Extension Filters (<code>:.ext</code> or <code>:.ext1.ext2</code>) <a class="header-anchor" href="#specific-extension-filters-ext-or-ext1-ext2" aria-label="Permalink to &quot;Specific Extension Filters (`:.ext` or `:.ext1.ext2`)&quot;">​</a></h3><p>Use a dot prefix to specify one or more file extensions (automatically excludes folders):</p><ul><li><code>report :.pdf</code>: Retains only <code>.pdf</code> files.</li><li><code>data :.csv.xlsx</code>: Retains only <code>.csv</code> or <code>.xlsx</code> spreadsheet files.</li></ul><h3 id="result-sorting-file-folder-filters-scmaf" tabindex="-1">Result Sorting &amp; File/Folder Filters (<code>:[SCMAF]</code>) <a class="header-anchor" href="#result-sorting-file-folder-filters-scmaf" aria-label="Permalink to &quot;Result Sorting &amp; File/Folder Filters (`:[SCMAF]`)&quot;">​</a></h3><p>Use single letters to specify sorting attributes: <code>S</code> (Size), <code>C</code> (Created time), <code>M</code> (Modified time), <code>A</code> (Accessed time), <code>F</code> (Folder/File filter).</p><p>The bare letter indicates <strong>ascending order</strong> (smallest / oldest first); adding a minus <code>-</code> (as a prefix or suffix, e.g. <code>M-</code> or <code>:-M</code>) indicates <strong>descending order</strong> (largest / newest first) or inverted filtering:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Token Syntax</th><th style="text-align:left;">Effect</th><th style="text-align:left;">Typical Use Case</th></tr></thead><tbody><tr><td style="text-align:left;"><code>:S</code></td><td style="text-align:left;">Sort by file size ascending (smallest first)</td><td style="text-align:left;">Locate empty or tiny files</td></tr><tr><td style="text-align:left;"><code>:S-</code> or <code>:-S</code></td><td style="text-align:left;">Sort by file size descending (largest first)</td><td style="text-align:left;"><code>log :S-</code> (troubleshoot massive log files)</td></tr><tr><td style="text-align:left;"><code>:M</code></td><td style="text-align:left;">Sort by modified time ascending (oldest first)</td><td style="text-align:left;">Find stale, unmaintained files</td></tr><tr><td style="text-align:left;"><code>:M-</code> or <code>:-M</code></td><td style="text-align:left;">Sort by modified time descending (newest first)</td><td style="text-align:left;"><code>report :M-</code> (find recently edited documents)</td></tr><tr><td style="text-align:left;"><code>:C</code> / <code>:C-</code></td><td style="text-align:left;">Sort by creation time ascending / descending</td><td style="text-align:left;"><code>build :C-</code> (find latest build outputs)</td></tr><tr><td style="text-align:left;"><code>:A</code> / <code>:A-</code></td><td style="text-align:left;">Sort by access time ascending / descending</td><td style="text-align:left;"><code>project :A-</code> (find recently opened projects)</td></tr><tr><td style="text-align:left;"><code>:F</code></td><td style="text-align:left;"><strong>Folders only</strong> (filters out regular files)</td><td style="text-align:left;"><code>config :F</code> (find only directories named config)</td></tr><tr><td style="text-align:left;"><code>:-F</code> or <code>:F-</code></td><td style="text-align:left;"><strong>Files only</strong> (filters out folders/directories)</td><td style="text-align:left;"><code>config :-F</code> (find only files named config)</td></tr></tbody></table><h3 id="wildcard-secondary-filters-expression-or-expression" tabindex="-1">Wildcard Secondary Filters (<code>:?&lt;expression&gt;</code> or <code>?&lt;expression&gt;</code>) <a class="header-anchor" href="#wildcard-secondary-filters-expression-or-expression" aria-label="Permalink to &quot;Wildcard Secondary Filters (`:?&lt;expression&gt;` or `?&lt;expression&gt;`)&quot;">​</a></h3><p>Use standard Windows wildcards (<code>?</code> for single character, <code>*</code> for zero or more characters) for precise matching, supporting <code>|</code> or <code>;</code> for multiple OR conditions:</p><ul><li><code>mp4 :?(2026???????????)</code>: Matches video files containing <code>2026</code> followed by an 11-digit timestamp.</li><li><code>photo :?IMG_????.jpg|DSC_????.jpg</code>: Matches specific photo numbers across two camera formats.</li></ul><h3 id="path-segment-filters-path-expression" tabindex="-1">Path Segment Filters (<code>::&lt;path-expression&gt;</code>) <a class="header-anchor" href="#path-segment-filters-path-expression" aria-label="Permalink to &quot;Path Segment Filters (`::&lt;path-expression&gt;`)&quot;">​</a></h3><p>Requires ancestor directory names or the filename itself to match the specified fuzzy keyword:</p><ul><li><code>report ::2024</code>: Requires the parent folder hierarchy to contain <code>2024</code>.</li><li><code>main ::&quot;src\\core&quot;</code>: Requires files to be located under <code>src\\core</code> and its subdirectories.</li></ul><h3 id="chained-query-token-examples" tabindex="-1">Chained Query Token Examples <a class="header-anchor" href="#chained-query-token-examples" aria-label="Permalink to &quot;Chained Query Token Examples&quot;">​</a></h3><p>Tokens can be combined together after a single <code>:</code> prefix:</p><ul><li><code>report :@doc,M-</code>: Searches &quot;report&quot;, filters to documents, sorted by modified time descending (newest first).</li><li><code>backup :.zip,S-,:-F</code>: Searches &quot;backup&quot;, filters to <code>.zip</code> archives, sorted by size descending, files only.</li><li><code>icon ::assets,?*128*</code>: Searches &quot;icon&quot;, located under <code>assets</code> paths, with <code>128</code> size tags in the name.</li></ul><h2 id="_6-special-search-features" tabindex="-1">6. Special Search Features <a class="header-anchor" href="#_6-special-search-features" aria-label="Permalink to &quot;6. Special Search Features&quot;">​</a></h2><h3 id="bypassing-exclusion-rules-for-one-search" tabindex="-1">Bypassing Exclusion Rules for One Search <a class="header-anchor" href="#bypassing-exclusion-rules-for-one-search" aria-label="Permalink to &quot;Bypassing Exclusion Rules for One Search&quot;">​</a></h3><p>Prefix a query with <code>*</code> to temporarily bypass user-configured path exclusions, globs, and regular expressions in <a href="./settings/index-drives.html#exclusion-rules"><strong>Exclusion Rules</strong></a> for this single search, without modifying settings:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>*node_modules</span></span></code></pre></div><p>The leading <code>*</code> is stripped before matching. This only recalls already indexed files (excluded paths on network/WSL drives that were never indexed will not appear); system/hidden file filters remain active.</p><h3 id="result-type-trigger" tabindex="-1">Result Type Trigger <a class="header-anchor" href="#result-type-trigger" aria-label="Permalink to &quot;Result Type Trigger&quot;">​</a></h3><p>Under <strong>Settings → General → Quick Search Window → Result Type Priority</strong>, you can configure a single-character <strong>trigger</strong> for specific result types (Applications, Settings, File Categories, Plugins, Files, etc.).</p><p>Typing the trigger as the very first character in the quick search window displays only that result type, hiding all others:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>;vs</span></span></code></pre></div><p>If <code>;</code> is assigned to &quot;Applications&quot;, the above query searches Visual Studio exclusively among applications. In Quick and Inline search windows, History and Favorites remain pinned at the top regardless of triggers.</p><h2 id="_7-multilingual-aliases" tabindex="-1">7. Multilingual Aliases <a class="header-anchor" href="#_7-multilingual-aliases" aria-label="Permalink to &quot;7. Multilingual Aliases&quot;">​</a></h2><h3 id="chinese-filenames-pinyin-aliasing" tabindex="-1">Chinese filenames: pinyin aliasing <a class="header-anchor" href="#chinese-filenames-pinyin-aliasing" aria-label="Permalink to &quot;Chinese filenames: pinyin aliasing&quot;">​</a></h3><p>Bundled with the <code>PinyinAlias</code> plugin, Chinese filenames are searchable via pinyin out of the box with zero configuration:</p><ul><li><strong>Full Pinyin</strong>: Typing <code>chongqing</code> matches <code>重庆.docx</code>.</li><li><strong>Pinyin Initials</strong>: Typing <code>cq</code> also matches <code>重庆.docx</code>; typing <code>wzry</code> matches <code>王者荣耀.exe</code>.</li><li><strong>Polyphonic Characters</strong>: Common pronunciations are automatically indexed (e.g. <code>重庆</code> matches both <code>chongqing</code> and <code>zhongqing</code>).</li></ul><p>You can verify that <code>PinyinAlias</code> is active under <strong>Settings → Plugins</strong>.</p><h3 id="spanish-filenames-accent-aliasing" tabindex="-1">Spanish filenames: accent aliasing <a class="header-anchor" href="#spanish-filenames-accent-aliasing" aria-label="Permalink to &quot;Spanish filenames: accent aliasing&quot;">​</a></h3><p>Bundled with the <code>SpanishAlias</code> plugin, filenames containing Spanish accented characters (<code>á</code>, <code>é</code>, <code>í</code>, <code>ó</code>, <code>ú</code>, <code>ü</code>, <code>ñ</code>) can be searched seamlessly using unaccented ASCII letters:</p><ul><li>Typing <code>cancion</code> matches <code>Canción.mp3</code>.</li><li>Typing <code>nino</code> matches <code>Niño.txt</code>.</li><li>Typing <code>ciguena</code> matches <code>Cigüeña.png</code>.</li></ul><p>Matched characters (including accented vowels in the original name) are accurately highlighted. Manage the plugin under <strong>Settings → Plugins</strong>.</p><h2 id="_8-faq-favorites" tabindex="-1">8. FAQ &amp; Favorites <a class="header-anchor" href="#_8-faq-favorites" aria-label="Permalink to &quot;8. FAQ &amp; Favorites&quot;">​</a></h2><h3 id="favorites-not-custom-aliases" tabindex="-1">Favorites, not custom aliases <a class="header-anchor" href="#favorites-not-custom-aliases" aria-label="Permalink to &quot;Favorites, not custom aliases&quot;">​</a></h3><p>Lertaro does not provide a generic &quot;custom search alias/macro&quot; mechanism. The closest native solutions:</p><ul><li><a href="./settings/favorites.html"><strong>Favorites</strong></a>: pin any file, folder, or URL under a custom display name, making it searchable by that custom title (marked with a ★ icon in results).</li><li><strong>File Filters</strong> (see <a href="./instant-answers.html#file-filters"><strong>Instant Answers</strong></a>): bind a trigger keyword to chosen folders, then typing <code>keyword term</code> in the quick search window restricts a normal index search to those folders.</li></ul><p>If you want to trigger custom scripts or launch programs using custom keywords, see <a href="./instant-answers.html#custom-commands"><strong>Custom Commands</strong></a>.</p>',105)])])}const u=t(s,[["render",n]]);export{g as __pageData,u as default};
